std::wstring textOf(HWND h){int n=GetWindowTextLengthW(h);std::wstring s(n+1,L'\0');GetWindowTextW(h,s.data(),n+1);s.resize(n);return s;}
std::string utf8(const std::wstring& s){if(s.empty())return {};int n=WideCharToMultiByte(CP_UTF8,WC_ERR_INVALID_CHARS,s.data(),(int)s.size(),nullptr,0,nullptr,nullptr);if(!n)return {};std::string r(n,'\0');WideCharToMultiByte(CP_UTF8,WC_ERR_INVALID_CHARS,s.data(),(int)s.size(),r.data(),n,nullptr,nullptr);return r;}
std::wstring fromUtf8(const std::string& s){if(s.empty())return {};int n=MultiByteToWideChar(CP_UTF8,MB_ERR_INVALID_CHARS,s.data(),(int)s.size(),nullptr,0);if(!n)return {};std::wstring r(n,L'\0');MultiByteToWideChar(CP_UTF8,MB_ERR_INVALID_CHARS,s.data(),(int)s.size(),r.data(),n);return r;}
std::wstring trim(const std::wstring& s){auto a=s.find_first_not_of(L" \t\r\n");if(a==std::wstring::npos)return {};return s.substr(a,s.find_last_not_of(L" \t\r\n")-a+1);}
std::wstring windowsLines(const std::wstring& s){std::wstring o;o.reserve(s.size()+100);for(size_t i=0;i<s.size();++i){if(s[i]==L'\n'&&(i==0||s[i-1]!=L'\r'))o+=L'\r';o+=s[i];}return o;}
bool fileExists(const std::wstring& p){DWORD a=GetFileAttributesW(p.c_str());return a!=INVALID_FILE_ATTRIBUTES&&!(a&FILE_ATTRIBUTE_DIRECTORY);}
bool readBytes(const std::wstring& p,std::string& data,size_t limit){HANDLE h=CreateFileW(p.c_str(),GENERIC_READ,FILE_SHARE_READ,nullptr,OPEN_EXISTING,FILE_ATTRIBUTE_NORMAL,nullptr);if(h==INVALID_HANDLE_VALUE)return false;LARGE_INTEGER n;if(!GetFileSizeEx(h,&n)||n.QuadPart<0||(unsigned long long)n.QuadPart>limit){CloseHandle(h);return false;}data.resize((size_t)n.QuadPart);DWORD got=0;BOOL ok=data.empty()||ReadFile(h,data.data(),(DWORD)data.size(),&got,nullptr);CloseHandle(h);return ok&&(data.empty()||got==data.size());}
static std::wstring uniqueName(){GUID id;CoCreateGuid(&id);wchar_t t[64];StringFromGUID2(id,t,64);return t;}
bool writeAtomic(const std::wstring& path,const std::string& data,bool replace){std::wstring tmp=path+L"."+uniqueName()+L".tmp";HANDLE h=CreateFileW(tmp.c_str(),GENERIC_WRITE,0,nullptr,CREATE_NEW,FILE_ATTRIBUTE_NORMAL,nullptr);if(h==INVALID_HANDLE_VALUE)return false;DWORD wrote=0;bool ok=WriteFile(h,data.data(),(DWORD)data.size(),&wrote,nullptr)&&wrote==data.size()&&FlushFileBuffers(h);CloseHandle(h);if(ok)ok=MoveFileExW(tmp.c_str(),path.c_str(),MOVEFILE_WRITE_THROUGH|(replace?MOVEFILE_REPLACE_EXISTING:0));if(!ok)DeleteFileW(tmp.c_str());return ok;}
static bool number(const std::wstring& s,double& out){auto t=trim(s);if(t.empty())return false;std::wistringstream in(t);in.imbue(std::locale::classic());in>>out;if(in.fail()||!std::isfinite(out))return false;in>>std::ws;return in.eof();}
Check validate(const Input& input){if(input.v.size()!=10)return {0,L"出生资料不完整。"};const auto& f=input.v;for(int i=0;i<10;i++)if(f[i].find_first_of(L"\r\n")!=std::wstring::npos||f[i].size()>200)return {i,L"输入包含无效字符或过长。"};if(f[1]!=L"0"&&f[1]!=L"1")return {1,L"请选择性别。"};double n[10]={};const wchar_t* labels[]={L"姓名",L"性别",L"年份",L"月份",L"日期",L"小时",L"分钟",L"经度",L"纬度",L"UTC 偏移"};for(int i=2;i<10;i++)if(!number(f[i],n[i]))return {i,std::wstring(L"请填写有效的")+labels[i]+L"。"};for(int i=2;i<=6;i++)if(n[i]!=std::floor(n[i]))return {i,std::wstring(labels[i])+L"必须是整数。"};if(n[2]<1800||n[2]>2100)return {2,L"年份范围为 1800—2100。"};if(n[3]<1||n[3]>12)return {3,L"月份范围为 1—12。"};int y=(int)n[2],m=(int)n[3];int days[]={31,28,31,30,31,30,31,31,30,31,30,31};if(y%4==0&&(y%100!=0||y%400==0))days[1]=29;if(n[4]<1||n[4]>days[m-1])return {4,L"这一天不存在，请检查日期。"};if(n[5]<0||n[5]>23)return {5,L"小时范围为 0—23。"};if(n[6]<0||n[6]>59)return {6,L"分钟范围为 0—59。"};if(n[7]<-180||n[7]>180)return {7,L"经度范围为 −180—180，东经为正。"};if(n[8]<-89||n[8]>89)return {8,L"纬度范围为 −89—89，北纬为正。"};if(n[9]<-12||n[9]>14||std::abs(n[9]*60-std::round(n[9]*60))>1e-7)return {9,L"UTC 偏移范围为 −12—14，需精确到整分钟。"};return {};}
bool engineAvailable(const std::wstring& home) {
 const auto separator = home.find_last_of(L"\\/");
 if (separator == std::wstring::npos) return false;
 const auto runtime = home.substr(0, separator);
 return fileExists(home+L"\\moira_s.prop") && fileExists(home+L"\\cities.prop") &&
        fileExists(runtime+L"\\bin\\moira-engine.exe");
}
static std::wstring q(const std::wstring& s){return L"\""+s+L"\"";}
bool computeChart(const Input& input,const std::wstring& dir,const std::wstring& home,std::wstring& result,HANDLE cancel){auto check=validate(input);if(!check){result=check.message;return false;}if(!engineAvailable(home)){result=L"内置计算核心或星历资料不完整。";return false;}if(!fileExists(dir+L"\\bin\\moira-engine.exe")){result=L"程序的计算文件不完整，请恢复 runtime 文件夹。";return false;}
 std::string data="moira\n";for(auto& f:input.v){data+=utf8(f);data+='\n';}SECURITY_ATTRIBUTES sa={sizeof(sa),nullptr,TRUE};HANDLE ir=nullptr,iw=nullptr,orr=nullptr,ow=nullptr;
 if(!CreatePipe(&ir,&iw,&sa,0)||!CreatePipe(&orr,&ow,&sa,0)){if(ir)CloseHandle(ir);if(iw)CloseHandle(iw);if(orr)CloseHandle(orr);if(ow)CloseHandle(ow);result=L"无法创建本地计算通道。";return false;}
 SetHandleInformation(iw,HANDLE_FLAG_INHERIT,0);SetHandleInformation(orr,HANDLE_FLAG_INHERIT,0);STARTUPINFOW si={sizeof(si)};si.dwFlags=STARTF_USESTDHANDLES|STARTF_USESHOWWINDOW;si.wShowWindow=SW_HIDE;si.hStdInput=ir;si.hStdOutput=ow;si.hStdError=ow;PROCESS_INFORMATION pi={};
 std::wstring executable=dir+L"\\bin\\moira-engine.exe";
 std::wstring cmd=q(executable)+L" --stdin-path";
 BOOL ok=CreateProcessW(executable.c_str(),cmd.data(),nullptr,nullptr,TRUE,CREATE_NO_WINDOW,nullptr,dir.c_str(),&si,&pi);CloseHandle(ir);CloseHandle(ow);if(!ok){CloseHandle(iw);CloseHandle(orr);result=L"无法启动内置计算核心，请检查 runtime 文件夹是否完整。";return false;}DWORD wrote=0;bool writeOK=WriteFile(iw,data.data(),(DWORD)data.size(),&wrote,nullptr)&&wrote==data.size();CloseHandle(iw);
 std::string bytes;char buf[8192];DWORD got=0;bool timeout=false,large=false,cancelled=false;ULONGLONG end=GetTickCount64()+30000;
 for(;;){if(cancel&&WaitForSingleObject(cancel,0)==WAIT_OBJECT_0){cancelled=true;break;}DWORD available=0;if(!PeekNamedPipe(orr,nullptr,0,nullptr,&available,nullptr))break;if(available){DWORD n=(std::min<DWORD>)(available,sizeof(buf));if(!ReadFile(orr,buf,n,&got,nullptr)||!got)break;if(bytes.size()+got>4*1024*1024){large=true;break;}bytes.append(buf,got);continue;}if(WaitForSingleObject(pi.hProcess,0)==WAIT_OBJECT_0)break;if(GetTickCount64()>end){timeout=true;break;}Sleep(15);}
 if(timeout||large||cancelled)TerminateProcess(pi.hProcess,1);CloseHandle(orr);WaitForSingleObject(pi.hProcess,5000);DWORD code=1;GetExitCodeProcess(pi.hProcess,&code);CloseHandle(pi.hThread);CloseHandle(pi.hProcess);result=windowsLines(fromUtf8(bytes));if(cancelled)result=L"已取消本次计算。";else if(timeout)result=L"内置计算超时，请稍后重试。";else if(large)result=L"结果过大，已停止读取。";if(!writeOK||code!=0||timeout||large||cancelled||result.empty()){if(result.empty())result=L"计算未返回有效文字。";return false;}return true;
}
static std::vector<std::wstring> split(const std::wstring& s,wchar_t sep){std::vector<std::wstring> o;std::wstring t;for(auto c:s){if(c==sep){o.push_back(t);t.clear();}else t+=c;}o.push_back(t);return o;}
std::vector<City> loadCities(const std::wstring& home){std::string b;if(!readBytes(home+L"\\cities.prop",b,4*1024*1024)||b.size()<2)return {};std::wstring s;if((unsigned char)b[0]==0xff&&(unsigned char)b[1]==0xfe){for(size_t i=2;i+1<b.size();i+=2)s+=(wchar_t)((unsigned char)b[i]|((unsigned char)b[i+1]<<8));}else if((unsigned char)b[0]==0xfe&&(unsigned char)b[1]==0xff){for(size_t i=2;i+1<b.size();i+=2)s+=(wchar_t)(((unsigned char)b[i]<<8)|(unsigned char)b[i+1]);}else return {};std::vector<City> result;int section=0;for(auto& line:split(s,L'\n')){auto t=trim(line);if(t==L"---"){section++;continue;}if((section!=0&&section!=2)||t.empty()||t[0]==L'#')continue;auto f=split(t,L'|');if(f.size()<4)continue;double lon,lat;if(!number(f[2],lon)||!number(f[3],lat)||std::abs(lon)>180||std::abs(lat)>89)continue;result.push_back({trim(f[0]),trim(f[1]),trim(f[2]),trim(f[3]),f.size()>4?trim(f[4]):L""});}return result;}
std::vector<Profile> loadProfiles(const std::wstring& dir){std::vector<Profile> out;WIN32_FIND_DATAW fd;HANDLE h=FindFirstFileW((dir+L"\\*.mprofile").c_str(),&fd);if(h==INVALID_HANDLE_VALUE)return out;do{if(fd.dwFileAttributes&(FILE_ATTRIBUTE_DIRECTORY|FILE_ATTRIBUTE_REPARSE_POINT))continue;std::wstring path=dir+L"\\"+fd.cFileName;std::string b;if(!readBytes(path,b,65536))continue;auto lines=split(fromUtf8(b),L'\n');if(lines.size()<11||trim(lines[0])!=L"MOIRA_NATIVE_PROFILE_1")continue;Input input;for(int i=1;i<=10;i++){auto s=lines[i];if(!s.empty()&&s.back()==L'\r')s.pop_back();input.v.push_back(s);}if(!validate(input))continue;out.push_back({path,input,fd.ftLastWriteTime});}while(FindNextFileW(h,&fd));FindClose(h);std::sort(out.begin(),out.end(),[](const Profile& a,const Profile& b){return CompareFileTime(&a.modified,&b.modified)>0;});return out;}
bool saveProfile(const std::wstring& dir,const Input& input,std::wstring& path){if(!validate(input))return false;if(!CreateDirectoryW(dir.c_str(),nullptr)&&GetLastError()!=ERROR_ALREADY_EXISTS)return false;std::string b="MOIRA_NATIVE_PROFILE_1\n";for(auto& f:input.v){b+=utf8(f);b+='\n';}path=dir+L"\\"+uniqueName()+L".mprofile";return writeAtomic(path,b);}
bool removeProfile(const std::wstring& dir,const std::wstring& path){if(path.substr(0,dir.size()+1)!=dir+L"\\")return false;std::wstring trash=dir+L"\\trash";if(!CreateDirectoryW(trash.c_str(),nullptr)&&GetLastError()!=ERROR_ALREADY_EXISTS)return false;auto p=path.find_last_of(L"\\/");return MoveFileExW(path.c_str(),(trash+L"\\"+uniqueName()+path.substr(p+1)).c_str(),MOVEFILE_WRITE_THROUGH);}
bool copyUnicode(HWND owner,const std::wstring& text,DWORD expectedSequence){if(text.empty())return false;SIZE_T bytes=(text.size()+1)*sizeof(wchar_t);HGLOBAL m=GlobalAlloc(GMEM_MOVEABLE,bytes);if(!m)return false;void* p=GlobalLock(m);if(!p){GlobalFree(m);return false;}memcpy(p,text.c_str(),bytes);GlobalUnlock(m);if(!OpenClipboard(owner)){GlobalFree(m);return false;}if(expectedSequence!=0xffffffff&&GetClipboardSequenceNumber()!=expectedSequence){GlobalFree(m);CloseClipboard();return false;}if(!EmptyClipboard()){GlobalFree(m);CloseClipboard();return false;}if(!SetClipboardData(CF_UNICODETEXT,m)){GlobalFree(m);CloseClipboard();return false;}CloseClipboard();return true;}
std::vector<std::wstring> splitResult(const std::wstring& result){std::wstring marker=L"【四柱八字】";size_t p=result.find(marker);if(p==std::wstring::npos)return {result,result,L""};size_t header=result.find(L"\r\n\r\n");std::wstring bazi=(header!=std::wstring::npos?result.substr(0,header)+L"\r\n\r\n":L"")+result.substr(p);return {result,trim(result.substr(0,p)),bazi};}


